package com.partychat;

import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * PartyChatMessage was taken, so PartyChatChatMessage it is.
 */
@Value
@EqualsAndHashCode(callSuper = false)
public class PartyChatChatMessage extends PartyMemberMessage
{
	String message;
}

package com.partychat;

import java.awt.Color;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup(PartyChatConfig.GROUP)
public interface PartyChatConfig extends Config
{
	String GROUP = "partychat";

	@ConfigItem(
		keyName = "sendKeybind",
		name = "Open party chat",
		description = "Hotkey that opens the party chat input box",
		position = 0
	)
	default Keybind sendKeybind()
	{
		return new Keybind(KeyEvent.VK_SLASH, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "messageColor",
		name = "Message colour",
		description = "Colour used for the message text",
		position = 1
	)
	default Color messageColor()
	{
		return new Color(255, 144, 144);
	}

}

package com.partychat;

import com.google.inject.Provides;

import java.awt.*;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.Objects;
import java.util.function.Consumer;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.Text;

/**
 * RuneLite party chat.
 */
@Slf4j
@PluginDescriptor(
	name = "Party Chat",
	description = "A party-chat for the RuneLite Party",
	tags = {"party", "chat", "clan", "friends", "b11"}
)
public class PartyChatPlugin extends Plugin
{
	private static final int MAX_LENGTH = 150;
	private static final long MIN_SEND_INTERVAL_MS = 600; // Just in case really

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PartyChatConfig config;

	@Inject
	private Client client;

	private long lastSentAt;

	@Provides
	PartyChatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PartyChatConfig.class);
	}

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.sendKeybind())
	{
		@Override
		public void hotkeyPressed()
		{
			openInput();
		}
	};

	@Override
	protected void startUp()
	{
		wsClient.registerMessage(PartyChatChatMessage.class);
		keyManager.registerKeyListener(hotkeyListener);
		log.debug("Party Chat started");
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkeyListener);
		wsClient.unregisterMessage(PartyChatChatMessage.class);
		lastSentAt = 0;
		log.debug("Party Chat stopped");
	}

	private void openInput()
	{
		if (!partyService.isInParty())
		{
			post(null, "You are not in a party.");
			return;
		}

		clientThread.invokeLater(() ->
			chatboxPanelManager.openTextInput("Party message")
				.onDone((Consumer<String>) this::trySend)
				.build()
		);
	}

	private void trySend(String rawInput)
	{
		String message = sanitize(rawInput);
		if (message.isEmpty() || !partyService.isInParty())
		{
			return;
		}

		long now = System.currentTimeMillis();
		if (now - lastSentAt < MIN_SEND_INTERVAL_MS)
		{
			return;
		}
		lastSentAt = now;

		partyService.send(new PartyChatChatMessage(message));
	}


	private static String formatKeybind(Keybind keybind)
	{
		StringBuilder sb = new StringBuilder();

		int modifiers = keybind.getModifiers();

		if ((modifiers & InputEvent.CTRL_DOWN_MASK) != 0)
		{
			sb.append("Ctrl + ");
		}

		if ((modifiers & InputEvent.SHIFT_DOWN_MASK) != 0)
		{
			sb.append("Shift + ");
		}

		if ((modifiers & InputEvent.ALT_DOWN_MASK) != 0)
		{
			sb.append("Alt + ");
		}

		sb.append(KeyEvent.getKeyText(keybind.getKeyCode()));

		return sb.toString();
	}

	@Subscribe public void onUserJoin(UserJoin event) {
		PartyMember sender = partyService.getMemberById(event.getMemberId());
		PartyMember local = partyService.getLocalMember();
		if (local.getMemberId() == sender.getMemberId())
		{
			post(null, "Party \"" + partyService.getPartyPassphrase() + "\" joined. Press [" + formatKeybind(config.sendKeybind()) + "] to start chatting.");
		}
	}

	@Subscribe
	public void onPartyChatChatMessage(PartyChatChatMessage event)
	{
		if (!partyService.isInParty())
		{
			return;
		}

		PartyMember sender = partyService.getMemberById(event.getMemberId());
		String message = sanitize(event.getMessage());

		if (!message.isEmpty())
		{
			post(displayName(sender), message);
		}
	}

	private String displayName(PartyMember member)
	{
		if (Objects.equals(member.getDisplayName(), "<unknown>")) {
			PartyMember local = partyService.getLocalMember();
			String fallback = String.valueOf(member.getMemberId());

			if (local.getMemberId() == member.getMemberId()) {
				Player localPlayer = client.getLocalPlayer();

				if (localPlayer != null)
				{
					fallback = localPlayer.getName();
				}
			}

			log.debug("[Party Chat] {}", partyService.getMembers());
			return fallback;
		}

		return sanitize(member.getDisplayName());
	}

	private void post(String name, String message)
	{
		ChatMessageBuilder builder = new ChatMessageBuilder();
		builder.append("[")
				.append(new Color(144, 144, 255), "Party")
				.append("] ");

		if (name != null)
		{
			builder.append(name + ": ");
		}

		builder.append(config.messageColor(), message);

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(builder.build())
			.build());
	}

	private static String sanitize(String input)
	{
		if (input == null)
		{
			return "";
		}

		String s = Text.JAGEX_PRINTABLE_CHAR_MATCHER.retainFrom(input.trim())
				.replaceAll("[\\r\\n\\t<>]+", " ")
				.replaceAll("\\s+", " ")
				.trim();

		return s.length() > MAX_LENGTH ? s.substring(0, MAX_LENGTH) : s;
	}
}

package com.partychat;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PartyChatPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PartyChatPlugin.class);
		RuneLite.main(args);
	}
}
